import{_ as i,c as a,o as s,a5 as l}from"./chunks/framework.DuCYAsAJ.js";const k=JSON.parse('{"title":"Tinder 交友系统设计","description":"","frontmatter":{"title":"Tinder 交友系统设计","date":"2026-05-03T00:00:00.000Z","order":11},"headers":[],"relativePath":"posts/SystemDesign/tinder.md","filePath":"posts/SystemDesign/tinder.md","lastUpdated":1779463578000}'),t={name:"posts/SystemDesign/tinder.md"};function o(h,e,d,r,n,p){return s(),a("div",null,[...e[0]||(e[0]=[l(`<h2 id="tinder-交友系统设计" tabindex="-1">Tinder 交友系统设计 <a class="header-anchor" href="#tinder-交友系统设计" aria-label="Permalink to &quot;Tinder 交友系统设计&quot;">​</a></h2><p>Tinder 这类交友系统的核心体验，是让用户持续看到一组符合条件、距离足够近的候选人卡片，并通过左滑或右滑表达跳过或喜欢。当两个人都对彼此右滑时，系统需要立即形成 match，并通知双方。</p><p>从表面看，它像是一个 feed 页面加一个 swipe 写接口。但系统复杂度主要集中在三件事上：如何低延迟生成潜在匹配候选池，如何在高并发下保证 swipe 与 match 判断的一致性，以及如何避免把已经滑过的人反复展示给用户。</p><h3 id="问题定义与边界" tabindex="-1">问题定义与边界 <a class="header-anchor" href="#问题定义与边界" aria-label="Permalink to &quot;问题定义与边界&quot;">​</a></h3><h4 id="功能需求" tabindex="-1">功能需求 <a class="header-anchor" href="#功能需求" aria-label="Permalink to &quot;功能需求&quot;">​</a></h4><ul><li>用户能够创建个人资料和偏好设置</li><li>用户能够看到符合条件且距离足够近的候选人卡片</li><li>用户能够对候选人左滑 / 右滑</li><li>双方都右滑时，系统能够通知 match</li></ul><h4 id="非功能需求" tabindex="-1">非功能需求 <a class="header-anchor" href="#非功能需求" aria-label="Permalink to &quot;非功能需求&quot;">​</a></h4><ol><li>Swipe 一致性要强：互相右滑时不能漏掉 match</li><li>系统需要支撑大规模日活，例如 <code>20M DAU</code></li><li>候选池加载延迟要低，目标约 <code>&lt; 300ms</code></li><li>系统应避免重复展示已滑过的候选人</li></ol><h4 id="本文暂不展开" tabindex="-1">本文暂不展开 <a class="header-anchor" href="#本文暂不展开" aria-label="Permalink to &quot;本文暂不展开&quot;">​</a></h4><ul><li>图片上传</li><li>匹配后的私信聊天</li><li>超级喜欢、付费加速等高级功能</li><li>反作弊与假资料治理</li></ul><h3 id="核心实体、接口与数据模型" tabindex="-1">核心实体、接口与数据模型 <a class="header-anchor" href="#核心实体、接口与数据模型" aria-label="Permalink to &quot;核心实体、接口与数据模型&quot;">​</a></h3><h4 id="核心实体" tabindex="-1">核心实体 <a class="header-anchor" href="#核心实体" aria-label="Permalink to &quot;核心实体&quot;">​</a></h4><ul><li><code>User</code></li><li><code>Swipe</code></li><li><code>Match</code></li></ul><p>这里的 <code>User</code> 既是系统账号，也是会被别人展示和滑动的 profile。</p><p><code>Swipe</code> 至少要表达 <code>fromUserId</code>、<code>toUserId</code>、<code>direction</code>（例如 <code>left</code> 或 <code>right</code>）以及 <code>createdAt</code>。<code>Match</code> 则表示两个用户已经互相右滑。</p><h4 id="初始接口" tabindex="-1">初始接口 <a class="header-anchor" href="#初始接口" aria-label="Permalink to &quot;初始接口&quot;">​</a></h4><ul><li>更新资料：<code>POST /profile</code></li><li>获取候选池：<code>GET /feed?lat={lat}&amp;lon={lon}</code></li><li>提交滑动：<code>POST /swipes</code></li></ul><p>典型的 swipe 请求可以长成：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;toUserId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;u2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;direction&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;right&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h4 id="基础数据模型" tabindex="-1">基础数据模型 <a class="header-anchor" href="#基础数据模型" aria-label="Permalink to &quot;基础数据模型&quot;">​</a></h4><p><code>User</code> 包含 <code>userId</code>、<code>gender</code>、<code>interestedIn</code>、<code>age</code>、<code>interests</code>、<code>maxDistance</code>、<code>location</code>。</p><p><code>Swipe</code> 的主键为 <code>fromUserId + toUserId</code>，值为 <code>direction</code>、<code>createdAt</code>。</p><p><code>Match</code> 的主键为规范化后的 <code>(userA, userB)</code>。</p><h3 id="核心架构设计" tabindex="-1">核心架构设计 <a class="header-anchor" href="#核心架构设计" aria-label="Permalink to &quot;核心架构设计&quot;">​</a></h3><h4 id="一、用户能够创建资料和偏好" tabindex="-1">一、用户能够创建资料和偏好 <a class="header-anchor" href="#一、用户能够创建资料和偏好" aria-label="Permalink to &quot;一、用户能够创建资料和偏好&quot;">​</a></h4><p>资料更新链路可以先保持简单：<code>Client</code> 请求进入 <code>API Gateway</code>，再由 <code>Profile Service</code> 写入 <code>Profile DB</code>。当用户提交 <code>POST /profile</code> 时，服务保存年龄偏好、兴趣、最大距离、位置等信息。这一层的技术难度不高，但它会直接决定后续候选池生成时可以使用哪些过滤条件。</p><h4 id="二、用户能够看到潜在匹配候选池" tabindex="-1">二、用户能够看到潜在匹配候选池 <a class="header-anchor" href="#二、用户能够看到潜在匹配候选池" aria-label="Permalink to &quot;二、用户能够看到潜在匹配候选池&quot;">​</a></h4><p>基础方案，是每次用户打开 App 时直接查询数据库，把符合偏好条件的人查出来。伪 SQL 大概会像这样：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> age </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BETWEEN</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 18</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 35</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> interestedIn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;female&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lat </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BETWEEN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> userLat </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> maxDistance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> userLat </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> maxDistance</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lon </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BETWEEN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> userLon </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> maxDistance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> userLon </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> maxDistance;</span></span></code></pre></div><p>这个方案在功能上成立，但规模一上来就会吃力：地理位置查询本身很重，候选池还要叠加偏好筛选，并且必须排除已经滑过的人。因此，高层设计可以先把它作为基础版本；真正影响体验的低延迟候选生成，则放到后续深入讨论中解决。</p><h4 id="三、用户能够左右滑并形成-match" tabindex="-1">三、用户能够左右滑并形成 match <a class="header-anchor" href="#三、用户能够左右滑并形成-match" aria-label="Permalink to &quot;三、用户能够左右滑并形成 match&quot;">​</a></h4><p>基础版本可以单独引入 <code>Swipe Service</code> 和 <code>Swipe Store</code>。最直观的流程是：用户提交 swipe，系统先检查“对方之前是否已经对我右滑”；如果对方已经右滑，而且本次也是右滑，则创建 <code>Match</code>；无论是否形成 match，都把本次 swipe 记录持久化。</p><p>到这里，左滑 / 右滑能落库，双向右滑时能形成匹配。但这个基础版会遇到竞态条件，后面还需要继续优化。</p><h3 id="深入讨论" tabindex="-1">深入讨论 <a class="header-anchor" href="#深入讨论" aria-label="Permalink to &quot;深入讨论&quot;">​</a></h3><h4 id="一、如何让-feed-低延迟又符合地理位置筛选" tabindex="-1">一、如何让 feed 低延迟又符合地理位置筛选 <a class="header-anchor" href="#一、如何让-feed-低延迟又符合地理位置筛选" aria-label="Permalink to &quot;一、如何让 feed 低延迟又符合地理位置筛选&quot;">​</a></h4><p>直接在主数据库里做位置筛选通常会很慢，尤其是在用户量很大、位置持续变化的场景下。更合适的方向，是把“候选人检索”从通用数据库查询升级为 geospatial index，再在候选集合上叠加偏好过滤。</p><p>这里有两种典型路径。第一种是使用地理索引数据库或搜索引擎，例如 Elasticsearch / OpenSearch，或者支持 geo query 的数据库。系统可以先按位置快速筛出候选集合，再叠加年龄、兴趣、性别偏好等条件。第二种是把预计算与索引查询结合起来：对大多数用户，后台先准备一批候选池并写入缓存；当用户快滑完时，再从地理索引系统里补充新的候选。这样，候选池既不是完全实时生成，也不是完全静态预计算，而是 <code>cached feed</code> + <code>indexed realtime refill</code> 的混合模式。</p><h4 id="二、为什么要预计算候选池" tabindex="-1">二、为什么要预计算候选池 <a class="header-anchor" href="#二、为什么要预计算候选池" aria-label="Permalink to &quot;二、为什么要预计算候选池&quot;">​</a></h4><p>如果每次用户进入 App 都实时查询位置、偏好和已滑过集合，查询链路会很长，延迟也很难稳定压到 <code>&lt; 300ms</code>。更好的思路，是在后台提前给用户准备一批 profile stack。用户打开 App 时，服务直接从缓存中读取候选 ID，再批量补全 profile 详情。这样首屏候选卡片的加载延迟会明显降低。</p><p>常见做法是把候选池缓存到 Redis。每个用户保留一小批待滑 profile ID，当剩余候选不足时异步补货。这样在用户视角里，feed 会接近“无限可滑”；从系统角度看，本质是在用预计算和缓存换取稳定的低延迟。</p><h4 id="三、预计算候选池为什么会-stale" tabindex="-1">三、预计算候选池为什么会 stale <a class="header-anchor" href="#三、预计算候选池为什么会-stale" aria-label="Permalink to &quot;三、预计算候选池为什么会 stale&quot;">​</a></h4><p>预计算一旦引入，就会带来候选池过期的问题。常见情况包括：对方已经移动到很远的位置，对方修改了偏好后不再符合条件，或者对方已经被当前用户滑过但缓存还没来得及清掉。</p><p>因此，cached feed 不能被当成绝对真相，更像一个候选草稿池。在展示某个 profile 前，系统仍然应该做一层轻量校验，例如检查对方是否仍在距离范围内、是否已被当前用户滑过、是否仍满足基础偏好。预计算负责省掉大部分昂贵查询，展示前 validation 则负责兜住体验和正确性。</p><h4 id="四、如何避免把滑过的人再次展示" tabindex="-1">四、如何避免把滑过的人再次展示 <a class="header-anchor" href="#四、如何避免把滑过的人再次展示" aria-label="Permalink to &quot;四、如何避免把滑过的人再次展示&quot;">​</a></h4><p>重复展示已滑过的人会严重破坏体验。一个直接方案是在 <code>Swipe Store</code> 里保存每个用户的滑动历史，生成候选池时把这些 <code>toUserId</code> 排除掉。但如果每次都实时查询一个巨大的“已滑集合”，成本会很高。</p><p>更常见的做法是分层处理：持久化层保存完整 swipe 历史，缓存层维护用户最近的已滑 ID 集合，feed 生成时优先用缓存快速排除。这样既能避免重复展示，又不需要每次都把历史 swipe 全量拿出来过滤。</p><h4 id="五、如何保证-swipe-和-match-的一致性" tabindex="-1">五、如何保证 swipe 和 match 的一致性 <a class="header-anchor" href="#五、如何保证-swipe-和-match-的一致性" aria-label="Permalink to &quot;五、如何保证 swipe 和 match 的一致性&quot;">​</a></h4><p>最有代表性的竞态发生在双方几乎同时右滑时：A 对 B 右滑，B 也几乎同时对 A 右滑。两边都先查“对方是否已经右滑我”，查询时都还看不到对方的新记录，于是最后两边都写入了 swipe，但没有任何一边创建 match。结果是两个人明明已经互相喜欢，却永远看不到匹配结果。</p><p>因此，swipe 记录和“是否互相右滑”的判断，最好在一次原子操作里完成。一种实现方式是借助 Redis 的原子能力：用同一个 key 存两边的 swipe 状态，通过 Lua script 在一次执行里先写入自己的 swipe，再读取对方的 swipe，最后决定是否形成 match。这里的关键不是 Lua 本身，而是明确这条链路需要强一致 / 原子更新，不能依赖“先查再写”的分离流程。</p><h4 id="六、为什么单独拆出-swipe-service" tabindex="-1">六、为什么单独拆出 Swipe Service <a class="header-anchor" href="#六、为什么单独拆出-swipe-service" aria-label="Permalink to &quot;六、为什么单独拆出 Swipe Service&quot;">​</a></h4><p>Profile 更新和 swipe 写入的访问模式差异很大：用户修改资料的频率较低，而滑动行为的频率高得多。因此，把 <code>Swipe Service</code> 和 <code>Profile Service</code> 拆开更容易扩展。swipe 路径可以单独扩容，swipe 存储也可以按高写入场景优化，feed 读路径和 swipe 写路径不会互相拖累。这是一种按访问模式拆分服务的典型思路。</p><h4 id="七、如果候选池滑完了怎么办" tabindex="-1">七、如果候选池滑完了怎么办 <a class="header-anchor" href="#七、如果候选池滑完了怎么办" aria-label="Permalink to &quot;七、如果候选池滑完了怎么办&quot;">​</a></h4><p>即使有缓存池，活跃用户也可能很快滑完。因此系统通常会在候选池剩余不多时提前触发补货。例如，当剩余 profile 少于 <code>N</code> 个时，后台异步从索引系统拉取一批新的候选，再写回缓存。</p><p>这能让用户几乎感觉不到“加载下一批候选”的停顿。从体验角度看，feed 像是无限的；从系统角度看，这是典型的提前预取。</p><h4 id="八、虚假资料和过期位置如何处理" tabindex="-1">八、虚假资料和过期位置如何处理 <a class="header-anchor" href="#八、虚假资料和过期位置如何处理" aria-label="Permalink to &quot;八、虚假资料和过期位置如何处理&quot;">​</a></h4><p>这两个问题都很常见，但它们属于主链路之外的扩展治理。过期位置可以通过位置 TTL、进入 App 时重新上报位置、展示前复核等方式缓解。虚假资料则更接近风控 / trust &amp; safety 子系统，需要独立建模和评估，不适合混入候选池与 match 的主流程。</p><h3 id="整体链路" tabindex="-1">整体链路 <a class="header-anchor" href="#整体链路" aria-label="Permalink to &quot;整体链路&quot;">​</a></h3><h4 id="更新资料路径" tabindex="-1">更新资料路径 <a class="header-anchor" href="#更新资料路径" aria-label="Permalink to &quot;更新资料路径&quot;">​</a></h4><ol><li>用户请求 <code>POST /profile</code></li><li><code>Profile Service</code> 写入资料和偏好</li><li>后台异步更新其可被检索索引</li></ol><h4 id="获取候选池路径" tabindex="-1">获取候选池路径 <a class="header-anchor" href="#获取候选池路径" aria-label="Permalink to &quot;获取候选池路径&quot;">​</a></h4><ol><li>用户进入 App</li><li>系统优先从缓存里读取预计算候选池</li><li>展示前做轻量过滤，排除已滑过和明显 stale 的 profile</li><li>候选不足时，异步从地理索引 / 搜索系统补货</li></ol><h4 id="滑动路径" tabindex="-1">滑动路径 <a class="header-anchor" href="#滑动路径" aria-label="Permalink to &quot;滑动路径&quot;">​</a></h4><ol><li>用户左滑 / 右滑一个 profile</li><li>请求进入 <code>Swipe Service</code></li><li>Redis / 原子脚本写入本次 swipe</li><li>同时检查对方是否已右滑</li><li>若双方互相右滑，则创建 <code>Match</code></li><li>已滑对象写入排除集合，避免再次展示</li></ol><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>Tinder 交友系统的主线可以分为几步：</p><ol><li>先用 Profile、Swipe、Match 三个核心实体把问题边界立住</li><li>用地理位置 + 偏好筛选解释候选池的基本生成逻辑</li><li>用缓存候选池解决 feed 首屏低延迟</li><li>用索引系统做补货，解决“无限滑”的体验</li><li>用已滑集合避免重复展示</li><li>用原子 swipe + match 检查解决一致性问题</li></ol><p>整体来看，这套系统本质上是<strong>基于地理位置和偏好条件的候选推荐系统，外加一条需要强一致匹配判断的高频写链路</strong>。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li><a href="https://www.hellointerview.com/learn/system-design/problem-breakdowns/tinder" target="_blank" rel="noreferrer">Hello Interview 官方讲解：Tinder</a></li></ul>`,69)])])}const u=i(t,[["render",o]]);export{k as __pageData,u as default};
